const game=(species,title)=>({title,invitation:`mini_${species}_invite`,play:`mini_${species}_play`,hint:`mini_${species}_hint`,win:`mini_${species}_win`});
export const MINI_GAMES = {
  stegosaurus:game('stegosaurus','Stóra risaeðlupúslið'),
  brachiosaurus:game('brachiosaurus','Lauf í nestið'),
  trex:game('trex','Mylla með grameðlu'),
  spinosaurus:game('spinosaurus','Fiskapör'),
  parasaurolophus:game('parasaurolophus','Hermum eftir laginu'),
  pteranodon:game('pteranodon','Talnaleikur í skýjunum'),
};
const photo=(species,name,latin,filename,author,license,licenseUrl,imageAlt)=>({
  name,latin,image:`./assets/collection/${species}.webp`,imageAlt,
  credit:`${author} · ${license} · Minnkuð mynd á WebP-sniði`,
  source:`https://commons.wikimedia.org/wiki/File:${filename}`,license,licenseUrl,
  facts:['diet','size','special'].map((key,i)=>({title:['Matur','Stærð','Sérkenni'][i],text:MINI_NARRATION[`statue_${species}_${key}`],narration:`statue_${species}_${key}`})),
  more:{title:'Segðu mér meira',text:MINI_NARRATION[`statue_${species}_more`],narration:`statue_${species}_more`},
});
